        int32_t dz = abs((int32_t)core->snake_z[2] - (int32_t)core->snake_z[3]);
        int32_t min_dx = dx < (100 - dx) ? dx : (100 - dx);
        int32_t min_dz = dz < (100 - dz) ? dz : (100 - dz);
        int32_t dist = min_dx + min_dz;
        int32_t spatial = (100 - dist) > 0 ? (100 - dist) : 0;
        int32_t score = spatial * weight;
        core->wave_interference_ops_count++;
